(()=>{document.querySelector("input[name=name]"),document.querySelector("input[type=email]"),document.querySelector("textarea");const e=document.querySelector(".connect__btn"),t=(document.querySelectorAll(".connect__form div"),document.querySelector("form"));var n=[];for(let e=0;e<t.elements.length-1;e++){const c=t.elements[e];""==c.value.trim()&&n.push(c)}e.addEventListener("click",function(e){e.preventDefault(),n.length&&n.forEach(e=>{e.closest("div").classList.add("error")})})})();